import { resolveAppLayout, isSupportedBpmsoftLayout } from '@bpmsoft-agent/metadata-core'
import type { ProjectValidationResult } from '../shared/types'

/**
 * Validates a user-chosen folder as a BPMSoft project root, using the
 * already-tested `resolveAppLayout`/`isSupportedBpmsoftLayout` from
 * `@bpmsoft-agent/metadata-core` (milestone 1). Pure function — no Electron
 * API dependency — so it's unit-testable without a display.
 *
 * Also surfaces the sibling research directories (`Resources`,
 * `Autogenerated` and `conf/content`)
 * alongside `pkgRoot` — `resolveAppLayout` finds these regardless of which
 * subfolder the user actually picked (Pkg, BPMSoft.Configuration, or the app
 * root), as long as the real folder structure has them. The chat wires these
 * in as `additionalDirectories` so the agent can research BPMSoft's own
 * implementation, not just edit files under Pkg.
 */
export function validateBpmsoftProject(projectPath: string): ProjectValidationResult {
	const layout = resolveAppLayout(projectPath)
	if (!isSupportedBpmsoftLayout(layout)) {
		return {
			isValid: false,
			path: projectPath,
			kind: layout.kind,
			reason:
				'Папка не похожа на BPMSoft-проект — не найдено BPMSoft.Configuration/Pkg или Autogenerated. ' +
				'Выберите корень приложения, папку BPMSoft.Configuration, Pkg или папку конкретного пакета.'
		}
	}
	return {
		isValid: true,
		path: projectPath,
		kind: layout.kind,
		pkgRoot: layout.pkgRoot,
		appRoot: layout.appRoot,
		resourcesRoot: layout.resourcesRoot,
		autogeneratedRoot: layout.autogeneratedRoot,
		confContent: layout.confContent
	}
}
